NAME = 'Tausug: Tausug Kitab Injil'
BOOK = 'I John'

CHAPTERS = {
    1: {
        1: "Yari aku nagsulat kaniyu ha pasal hi Īsa Almasi, amu in Parman sin Tuhan, amu in magdirihil kabuhi' sabunnal. In siya asal awn na ha wala' pa naawn in dunya. Malayngkan diyungug namu' tuud in manga bichara niya, iban kīta' namu' tuud siya sin duwa mata namu'. Mattan kīta' namu' tuud siya lāgi' kiyaulinan namu' pa siya.",
        2: "In siya, amu in magdirihil kabuhi' salama-lama iban sin Ama' Tuhan asal hambuuk da, sagawa' limahil siya mari pa dunya nagbaran mānusiya'. Na, kīta' namu' tuud siya, hangkan sumaksi' kami mamayta' kaniyu sin pasal niya, amu in makarihil kabuhi' salama-lama, sabab piyanyata' siya sin Tuhan kāmu'.",
        3: "Na, hangkan baytaan ta kamu isab sin unu in bakas kīta' iban diyungug namu', ha supaya kamu makalamud sin paghambuuk namu' iban sin Ama' Tuhan iban sin amu in Anak niya hi Īsa Almasi.",
        4: "Hangkan yari aku nagsulat kaniyu sin pasal yan ha supaya jumukup in kakuyagan natu' katān.",
        5: "Na, bihaun hibayta' namu' kaniyu in bayta' diyungug namu' dayn kan Īsa Almasi, amu agi, Tuhan in puunan sin kasawahan iban wayruun tuud unu-unu katigidluman guwa' dayn kaniya.",
        6: "Na, bang kitaniyu sawpama umiyan naghahambuuk kitaniyu iban Tuhan, sagawa' himihinang da kitaniyu sin manga hinang ha katigidluman, hāti niya naghihinang da sin bukun mabuntul, na puting in bichara taniyu sabab wala' natu' da iyaagad in hindu' kasabunnalan.",
        7: "Sagawa' bang kitaniyu miyamanaw ha kasawahan, hāti niya naghihinang sin mabuntul biya' sin Tuhan, amu in puunan sin kasawahan, na in kitaniyu naghahambuuk tuud, iban puas in katān manga dusa taniyu dayn ha sabab sin dugu' naasag ha kamatay hi Īsa, amu in Anak Tuhan.",
        8: "Na, bang kitaniyu umiyan way dusa taniyu, na iyakkalan taniyu in baran natu' iban in kasabunnalan sin Tuhan wayruun ha lawm atay natu'.",
        9: "Sagawa' bang kitaniyu magsabunnal pa Tuhan sin manga dusa nahinang taniyu, na tantu ampunun kitaniyu sin Tuhan iban īgan niya in unu-unu katān mangī' ha lawm atay taniyu, sabab in siya mabuntul iban kapangandulan taniyu sin agarun niya tuud in janji' niya.",
        10: "Na, bang kitaniyu umiyan sin way kitaniyu nakahinang sin unu-unu makarusa, na piyanghimuting natu' in Tuhan iban in Parman niya wala' himūp pa lawm atay taniyu.",
    },
    2: {
        1: "Na, in kamu manga anak-apu' ku, hangkan aku nagsulat kaniyu pasal sin manga palihālan nasabbut ku, ha supaya kamu di' makahinang sin manga makarusa. Sagawa' bang sawpama awn hambuuk kātu'niyu in magdusa, na, awn hambuuk tau mabuntul tuud in tumabang kātu'niyu mangayu' kaampunan pa Ama' Tuhan. In siya ini amuna hi Īsa Almasi.",
        2: "Lāgi', in dugu'-nyawa hi Īsa Almasi amuna in nakapapas sin manga dusa natu', iban bukun sadja isab manga dusa natu', sagawa' iyakuhan niya in dusa sin mānusiya' katān.",
        3: "Na, bang kitaniyu magkahagad huminang sin manga daakan sin Tuhan, na yan amuna in tanda' tuud sin in kitaniyu agad tuud ha Tuhan.",
        4: "Bang awn tau umiyan in siya agad ha Tuhan, sagawa' wala' niya da iyaagad in manga daakan sin Tuhan, na in tau yan putingan iban wayruun kasabunnalan ha lawm atay niya.",
        5: "Sagawa' hisiyu-siyu in magkahagad ha Parman sin Tuhan, na in lasa niya ha Tuhan dayn ha bigi-jantung niya tuud. Na, amu ini in tanda' sin in kitaniyu naghahambuuk tuud iban Tuhan bang kitaniyu magkahagad kaniya.",
        6: "Hisiyu-siyu in umiyan sin in siya naghahambuuk iban Tuhan, subay in kawl-piil niya biya' sin kawl-piil hi Īsa Almasi.",
        7: "Manga taymanghud ku kalasahan, in daakan hisulat ku kaniyu bihaun bukun ba'gu gimuwa', karna' in daakan ini pasal sin subay kamu maglasa-liyasahi, bakas niyu na diyungug niyasīhat kaniyu ha waktu tagna' niyu nagparachaya ha Almasi.",
        8: "Malayngkan minsan isab bakas niyu na diyungug in daakan ini, na maitung da isab ini hambuuk daakan ba'gu, sabab dayn ha nahinang sin Almasi iyampa natu' kīta' bang biya' diin tuud in bunnal pagkasi-lasa. Damikkiyan in kamu piyakikita' niyu da isab in pagkasi-lasa niyu, sabab kiyarihilan na kasawahan in pamikil niyu. Na, masuuk na maīg in katigidluman sabab simi'nag na in kasawahan, amu in hindu' bunnal naug dayn ha Tuhan.",
        9: "Na, hisiyu-siyu in umiyan sin in siya ha lawm kasawahan miyamagad sin daakan sin Tuhan, sagawa' marugal siya ha pagkahi niya, na in siya yan masi ha lawm katigidluman, masi wala' miyamagad sin daakan sin Tuhan.",
        10: "Hisiyu-siyu in bunnal malasa ha pagkahi niya, na in siya yan ha lawm kasawahan sin Tuhan, miyamagad sin daakan niya. Hangkan wayruun unu-unu mangī' ha lawm atay niya amu in makarā kaniya huminang sin makarusa.",
        11: "Sagawa' hisiyu-siyu in marugal ha pagkahi niya, in siya yan ha lawm katigidluman. Mangī' in hinang niya. Miyamanaw siya ha lawm katigidluman, iban di' niya kaingatan bang siya harap pakain, sabab wayruun unu-unu kakitaan niya ha lawm katigidluman.",
        12: "Na, sulatan ta kamu manga anak-apu' ku, sabab in manga dusa niyu iyampun na sin Tuhan sabab sin nahinang sin Almasi.",
        13: "Sulatan ta kamu manga tau-maas, sabab in kamu agad na kan Īsa Almasi, amu in asal na awn ha wala' pa napaawn in unu-unu katān. Sulatan ta kamu manga bata'-ba'gu, sabab wala' kamu narā sin sasat sin Saytan Puntukan, amu in puunan sin katān kangīan. Sulatan ta kamu manga anak-apu' ku, sabab in kamu agad na ha Tuhan Ama' natu'.",
        14: "Sulatan ta kamu manga tau-maas, sabab in kamu agad na ha Almasi, amu in asal na awn ha wala' pa napaawn in unu-unu katān. Sulatan ta kamu manga bata'-ba'gu, sabab makusug na in parachaya niyu ha Almasi, lāgi' biyubutang niyu tuud in Parman sin Tuhan ha lawm atay niyu, iban wala' tuud kamu narā sin sasat sin Saytan, amu in puunan sin katān kangīan.",
        15: "Ayaw niyu pahalgaa ha lawm atay niyu in manga hinang iban addat-tabīat sin manga tau bukun agad ha Tuhan, iban ayaw niyu pahalgaa ha lawm atay niyu in unu-unu amu in suku' sadja sin dunya. Karna' bang amu ini in pahalgaun niyu ha lawm atay niyu, na wayruun lasa niyu ha Tuhan, Ama' natu'.",
        16: "Karna' in unu-unu katān hinang mangī' dī ha dunya biya' na sin hawa-napsu sin anggawta'-baran, magnapsu sin unu-unu katān kakitaan iban kabayaan iban sin pagbantug sadja sin alta', bukun yan guwa' dayn ha Tuhan Ama' natu', sabab in manga katān hinang mangī' biya' ha yan guwa' dayn ha pikilan sin tau bukun agad ha Tuhan.",
        17: "In dunya ini iban sin unu-unu katān luun niya, amu in pagnapsuhan sin manga mānusiya', in kasūngan niya malanyap da; sagawa' in tau magkahagad huminang sin kabayaan sin Tuhan, awn kabuhi' niya kasaumulan didtu ha surga'.",
        18: "Na, manga anak-apu' ku, masuuk na in kahinapusan sin masa taniyu. Bakas na kamu isab kiyabaytaan sin bang masuuk na in kahinapusan sin masa gumuwa' na in Tau Lidjal amu in kumuntara tuud ha Almasi. Na, bihaun timaud na tuud in kimuntara ha Almasi, hangkan kaingatan natu' sin masuuk na in kahinapusan sin masa.",
        19: "Na, in manga kimukuntara ini ha Almasi tagna' bakas hangka-agaran iban kitaniyu, sagawa' miyutas na sila dayn kātu'niyu. In sila yan bukun tuud hangka-atay iban kitaniyu, sabab bang sila yan hangka-atay iban kitaniyu, di' sila mutas dayn kātu'. Sagawa' miyutas sila dayn kātu', hangkan tumampal na sin in sila mattan tuud bukun hangka-agaran iban kitaniyu.",
        20: "Sagawa' in kamu bukun sibu' iban sila, sabab piyahūp na sin Almasi in Rū sin Tuhan mawn kaniyu. Hangkan in kamu katān makaingat sin hindu' kasabunnalan.",
        21: "Sulatan ta kamu bukun pasal awam kamu sin hindu' kasabunnalan, sagawa' pasal kaingatan niyu in hindu' kasabunnalan, iban kaingatan niyu da isab sin wayruun puting in gumuwa' dayn ha hindu' kasabunnalan.",
        22: "Na, hisiyu baha' in putingan? Mattan hisiyu-siyu in umiyan sin in hi Īsa bukun Almasi, amu in kiyawakilan sin Tuhan magbaya' ha unu-unu katān, na in tau yan tantu tuud putingan. In tau yan kuntara sin Almasi. Di' siya magkahagad ha Ama' Tuhan iban di' siya magkahagad ha Anak Tuhan.",
        23: "Karna' hisiyu-siyu in di' magkahagad sin in hi Īsa Almasi amuna in Anak Tuhan, na hāti niya di' da isab siya magkahagad ha Ama' Tuhan. Sagawa' hisiyu-siyu in tumampal magsabunnal sin in hi Īsa amuna in Almasi Anak Tuhan, in siya yan nagkahagad tuud ha Tuhan, Ama' natu'.",
        24: "Na, hangkan pahūpa tuud pa lawm atay niyu in nasīhat bakas niyu diyungug tagna'. Bang niyu pahūpun pa lawm atay niyu in nasīhat yan, na tumutug in paghambuuk niyu iban sin Almasi amu in Anak Tuhan iban sin Ama' Tuhan,",
        25: "sabab jiyanjian kitaniyu sin Almasi dihilan kabuhi' salama-lama.",
        26: "Sulatan ta kamu ha supaya kamu makahalli' dayn ha manga tau amu in manghindu' kaniyu sin bukun kasabunnalan bat kamu marā pa kalawngan.",
        27: "Sagawa' in kamu, piyahūp na sin Almasi in Rū sin Tuhan, mawn kaniyu, hangkan di' na kamu magkalagihan tau manghindu' kaniyu. Sabab in Rū sin Tuhan amu in manghindu' kaniyu sin unu-unu katān, iban in katān hindu' niya bunnal, bukun puting. Kahagara niyu in hindu' sin Rū sin Tuhan iban patutuga niyu tuud in paghambuuk niyu iban sin Almasi.",
        28: "Na, pagga biya' ha yan in kahālan, manga anak-apu' ku, patutuga niyu tuud in paghambuuk niyu iban sin Almasi ha supaya kitaniyu di' muga' iban di' sumipug umalup kaniya bang siya magbalik na mari pa dunya.",
        29: 'Na, kaingatan niyu sin mabuntul tuud in Almasi, hangkan kaingatan niyu da isab sin hisiyu-siyu in maghinang sin mabuntul, in siya yan anak sin Tuhan.',
    },
    3: {
        1: "Na, dungug kamu! In Ama' Tuhan landu' tuud malasa kātu'niyu, hangkan dayn ha sabab landu' tuud in lasa niya kātu'niyu, ītung niya kitaniyu manga anak niya. Na, mattan tuud in kitaniyu nahinang na anak niya! Sagawa' di' kitaniyu kahātihan sin manga tau, amu in nagpaparuli sadja sin manga kahālan dī ha dunya, sabab wala' nila da isab kiyahātihan in Tuhan.",
        2: "Manga taymanghud ku kalasahan, bihaun in kitaniyu ini anak na sin Tuhan, sagawa' bukun pa matampal bang unu in kaawnan natu'. Malayngkan, kaingatan natu' bang magbalik na in Almasi mari pa dunya, in kitaniyu mabiya' na kaniya, sabab kakitaan natu' na bang biya' diin tuud in dagbus niya.",
        3: "Na, hisiyu-siyu in magkahagad iban nagtatagad tuud sin pagdatung sin waktu ini, tantu pabuntulun niya tuud in atay niya biya' sin kabuntul sin atay sin Almasi.",
        4: "Hisiyu-siyu in maghinang sin makarusa, lumanggal da isab siya sin sara' sin Tuhan, sabab in maghinang sin makarusa manglanggal sara' sin Tuhan.",
        5: "Na, kaingatan niyu na sin in Almasi limahil mari pa dunya mamuas sin dusa sin manga mānusiya', ampa in Almasi wayruun tuud dusa niya.",
        6: "Hangkan hisiyu-siyu in naghahambuuk iban sin Almasi, nalawa' na in baya' niya maghinang sin manga makarusa. Sagawa' hisiyu-siyu in masi naghihinang sin manga makarusa, in siya yan wala' tuud nakahāti pasal sin Almasi, lāgi' bukun tuud agad kaniya.",
        7: "Na, manga anak-apu' ku, halli' tuud kamu dayn ha manga tau, amu in mangakkal mangdā kaniyu pa kalawngan. Hisiyu-siyu in maghinang sin mabuntul, na in atay niya mabuntul, biya' sin atay sin Almasi amu in mabuntul tuud.",
        8: "Hisiyu-siyu in masi maghinang sin makarusa, na in siya yan suku' sin Iblis, sabab in Iblis asal nagdusa dayn ha awwal tagna' pa. Na, dayn ha pasal ini limahil mari pa dunya in Anak Tuhan, ha supaya malubu in katān hinang mangī' sin Iblis.",
        9: "Hisiyu-siyu in anak na sin Tuhan, na nalawa' na in baya' niya maghinang sin makarusa, sabab in siya biya' na sin Tuhan, amu in di' maghinang sin unu-unu mangī'. Lāgi', way na baya' niya maghinang sin unu-unu makarusa, sabab in Tuhan amuna in Ama' niya.",
        10: "Na, biya' ha ini in piyagbiddaan sin manga tau anak sin Tuhan iban sin manga tau anak sin Iblis. Hisiyu-siyu in di' maghinang sin mabuntul iban di' malasa ha pagkahi niya, na in siya yan bukun anak sin Tuhan.",
        11: "In muna-muna tuud nasīhat diyungug niyu tagna', amuna in daakan sin subay kitaniyu maglasa-liyasahi.",
        12: "Ayaw niyu singuri in bakas nahinang hi Kābil amu in agad ha Saytan, amu in puunan sin katān kangīan. Piyatay niya in manghud niya. Na, mayta' niya piyatay in manghud niya? Na, sabab marayaw in manga hinang sin manghud niya, ampa in siya mangī' in manga hinang niya.",
        13: 'Na, hangkan manga taymanghud ku, ayaw kamu mainu-inu bang kamu kabunsihan sin manga tau, amu in bukun agad ha Tuhan.',
        14: "Kaingatan natu' in kitaniyu napinda na. In tagna' biya' kitaniyu hantang manga patay, hāti niya butas dayn ha Tuhan, sagawa' bihaun bunnal na tuud in kabuhi' natu', hāti niya naghambuuk na iban Tuhan. Kaingatan natu' ini, sabab malasa na kitaniyu ha pagkahi natu'. Hisiyu-siyu in di' malasa ha pagkahi niya, na masi siya biya' hantang patay.",
        15: "Hisiyu-siyu in mabunsi ha pagkahi niya, biya' da siya sin hambuuk māmunu', iban kaingatan niyu da isab sin in tau māmunu' wayruun kabuhi' niya salama-lama.",
        16: "Na, kaingatan natu' na bang biya' diin in bunnal pagkasi-lasa, sabab napakita' na kātu' sin Almasi sin dayn ha sabab sin kasi-lasa niya kātu'niyu, līlla' niya in dugu'-nyawa niya, ha supaya mapapas in manga dusa taniyu. Na, damikkiyan in kitaniyu, subay lilla' mapatay sabab-karna' sin pagkahi taniyu!",
        17: "Na, bang sawpama kakitaan sin hambuuk tau taga alta' in pagkahi niya kiyasisigpitan, ampa di' niya tabangun, na in siya yan way lasa niya ha Tuhan.",
        18: "Na, manga anak-apu' ku in pagkasi-lasa natu' subay bukun ha simud sadja, sagawa' subay natu' hipakita' in bunnal pagkasi-lasa dayn ha tulung-tabang taniyu ha pagkahi natu'.",
        19: "Na, bang bunnal in pagkasi-lasa natu', na makatantu kitaniyu sin iyaagad natu' tuud in hindu' kasabunnalan. Lāgi', dayn ha pasal ini wayruun kabugaan natu' mangarap pa Tuhan.",
        20: "Minsan da ha pikilan natu' matūp kitaniyu butangan hukuman sin Tuhan di' kitaniyu mahanggaw, sabab kaingatan natu' sin labi in dayaw sin hukuman sin Tuhan dayn sin hukuman natu', hukuman mānusiya', sabab in unu-unu katān kaingatan sin Tuhan.",
        21: "Na, hangkan manga taymanghud ku kalasahan, bang kitaniyu bukun mahanggaw pasal sin manga dusa taniyu, (sabab iyampun na kitaniyu sin Tuhan,) na di' na kitaniyu mabuga' mangarap pa Tuhan.",
        22: "Dihilan kitaniyu sin Tuhan sin unu-unu na pangayuun taniyu, sabab kiyahagad natu' in manga daakan niya iban hīhinang natu' in unu-unu makasulut kaniya.",
        23: "Ini in daakan sin Tuhan kātu'niyu: subay kitaniyu magparachaya kan Īsa Almasi, amu in Anak Tuhan, iban subay kitaniyu maglasa-liyasahi biya' da isab sin daakan kātu' sin Almasi.",
        24: "Hisiyu-siyu in magkahagad sin manga daakan sin Tuhan, in siya naghahambuuk iban Tuhan, iban taptap duun kaniya in Tuhan. Lāgi', kaingatan natu' naghahambuuk kitaniyu iban Tuhan ha sabab sin Rū niya piyahūp niya pa lawm atay taniyu.",
    },
    4: {
        1: "Manga taymanghud ku kalasahan, ayaw kamu magkahagad ha hisiyu-siyu sadja tau amu in umiyan hiyuhūp siya sin Rū sin Tuhan. Sagawa' dungdungi niyu na tuud marayaw in hindu' niya, ampa niyu kitaa bang siya hiyuhūp sin Rū sin Tuhan, atawa bukun. Karna' bihaun mataud na nabi bukun bunnal gimuwa' ha dunya.",
        2: "Na, biya' ha ini in pangitaan niyu bang in tau bunnal hiyuhūp sin Rū sin Tuhan. Hisiyu-siyu in magsabunnal manghindu' sin in hi Īsa Almasi miyari pa dunya nagbaran mānusiya', na in tau yan hiyuhūp sin Rū sin Tuhan.",
        3: "Sagawa' hisiyu-siyu in manghimuting sin hindu' ini pasal hi Īsa, na in tau yan wala' hiyūp sin Rū sin Tuhan sabab in hindu' niya yan guwa' dayn ha pikilan sin kuntara sin Almasi. Na, bakas niyu na diyungug sin magkakari pa dunya in kuntara sin Almasi, manglidjal ha manga mānusiya'. Na, bihaun timagna' na in manga tau miyagad ha pikilan sin kuntara sin Almasi.",
        4: "Sagawa' in kamu manga anak-apu' ku, suku' kamu sin Tuhan. Iban wala' kamu narā miyagad sin hindu' sin manga nabi bukun bunnal, sabab labi makawasa in Rū sin Tuhan, amu in himuhūp duun kaniyu, dayn sin Saytan Puntukan, amu in iyaagaran sin manga tau bukun agad ha Tuhan.",
        5: "In manga nabi bukun bunnal, hangka-agaran iban sin manga tau bukun agad ha Tuhan; hangkan manghindu' sadja sila sin manga palihālan, amu in malabi ha atay sin manga tau bukun agad ha Tuhan. Na, dungugun sila sin manga tau bukun agad ha Tuhan.",
        6: "Sagawa' in kitaniyu suku' sin Tuhan. Na, hisiyu-siyu in agad tuud ha Tuhan, na dumungug siya sin hindu' natu', sagawa' hisiyu-siyu in bukun suku' sin Tuhan, na di' dumungug sin hindu' natu'. Na, biya' ha yan in pangitaan natu' sin piyagbiddaan sin hindu' kasabunnalan dayn ha Tuhan iban sin hindu' pa kalawngan dayn ha Saytan Puntukan.",
        7: 'Manga taymanghud ku kalasahan, subay kitaniyu maglasa-liyasahi, sabab Tuhan in puunan sin pagkasi-lasa. Hisiyu-siyu in malasa ha pagkahi niya, in siya anak sin Tuhan iban kaingatan niya tuud in Tuhan.',
        8: "Hisiyu-siyu in di' malasa ha pagkahi niya, na di' niya kaingatan tuud in Tuhan, sabab in Tuhan puunan sin kasi-lasa bunnal.",
        9: "Lāgi', piyakita' na sin Tuhan bang biya' diin in lasa niya kātu'niyu. Piyalahil niya mari pa dunya in hambuuk-buuk Anak niya, ha supaya niya kitaniyu karihilan kabuhi' salama-lama dayn ha sabab sin nahinang sin Anak niya. Biya' ha yan in pagpakita' sin Tuhan sin lasa niya.",
        10: "Na, in bunnal pagkasi-lasa, amuna in biya' sin lasa sin Tuhan kātu'niyu, bukun lasa taniyu ha Tuhan, karna' piyalahil niya mari pa dunya in Anak niya limilla' sin dugu'-nyawa niya, ha supaya maampun in manga dusa taniyu. Na, in yan hīnang niya pasal sin asal siya malasa kātu'niyu.",
        11: "Na, manga taymanghud ku kalasahan, pagga biya' ha yan in laggu' sin lasa sin Tuhan kātu'niyu, na subay kitaniyu maglasa-liyasahi.",
        12: "Bunnal wayruun tau in nakakita' ha Tuhan, sagawa' bang kitaniyu maglasa-liyasahi, in Tuhan humambuuk kātu'niyu iban in lasa taniyu kaniya humūp na tuud pa lawm bigi-jantung taniyu.",
        13: "Matantu natu' sin himahambuuk kitaniyu ha Tuhan iban in siya himahambuuk da isab kātu'niyu, sabab sin Rū sin Tuhan piyahūp niya mari kātu'niyu.",
        14: "Bakas namu' kīta' tuud sin duwa mata namu' in Anak Tuhan, amu in piyalahil sin Tuhan mari pa dunya lumappas sin dusa sin manga mānusiya'. Na, biyabaytaan namu' in manga tau sin pasal niya.",
        15: 'Hisiyu-siyu in magsabunnal sin in hi Īsa amuna in Anak Tuhan, na in siya naghahambuuk iban Tuhan iban in Tuhan himahambuuk kaniya.',
        16: "Na, kaingatan iban natatantu natu' tuud sin malasa in Tuhan kātu'niyu. In Tuhan amu in puunan sin kasi-lasa bunnal. Na, hisiyu-siyu in malasa ha Tuhan iban ha pagkahi niya, na in siya himahambuuk ha Tuhan iban in Tuhan himahambuuk kaniya.",
        17: "In lasa taniyu pa Tuhan piyahūp niya tuud pa lawm bigi-jantung natu', ha supaya kitaniyu di' muga' bang dumatung na in waktu paghukum ha mānusiya' katān. Na, hangkan kitaniyu di' muga', sabab in kahālan natu' dī ha dunya biya' da isab sin kahālan sin Almasi.",
        18: "Na, wayruun kabugaan ta sin unu-unu na kamulahan dayn ha hisiyu-siyu na malasa tuud kātu'niyu. In bunnal tuud pagkasi-lasa makaīg sin unu-unu na kabugaan ta. Hisiyu-siyu in mabuga', hāti niya, wala' pa tuud himūp pa lawm atay niya in bunnal pagkasi-lasa, karna' hisiyu-siyu in mabuga' nagpipikil siya sin siksaun siya sin Tuhan.",
        19: "Naawn in pagkasi-lasa taniyu sabab Tuhan in muna limasa kātu'niyu.",
        20: "Bang awn tau umiyan malasa siya ha Tuhan, sagawa' mabunsi siya ha pagkahi niya, na in tau yan putingan. Karna' biya' diin in kalasa niya ha Tuhan, amu in wala' niya kīta', bang siya di' malasa ha pagkahi niya, amu in kīkita' niya?",
        21: "Na, biya' ha ini in daakan sin Almasi kātu'niyu. Hisiyu-siyu in malasa ha Tuhan, subay da isab siya malasa ha pagkahi niya.",
    },
    5: {
        1: "Hisiyu-siyu in magparachaya sin hi Īsa amuna in Almasi, (amu in kiyawakilan sin Tuhan magbaya' ha unu-unu katān) na in siya yan anak sin Tuhan. Na, biya' takdil ha kitaniyu mānusiya', bang kita malasa ha ama' ta, na awn da isab lasa taniyu ha manga anak niya, manga taymanghud ta. Na, biya' da isab ha yan in hantang sin lasa taniyu ha Tuhan.",
        2: "Bang kita malasa ha Tuhan iban iyaagad taniyu in manga daakan niya, na amuna in tanda' sin awn lasa taniyu ha manga anak niya, manga pagkahi taniyu.",
        3: 'Na, in hāti niya bang kita malasa ha Tuhan subay ta kahagarun in manga daakan niya. Ampa in manga daakan niya bukun mahunit hinangun,',
        4: "sabab in sasuku' anak sin Tuhan di' marā sin sasat dī ha dunya, iban hangkan kitaniyu di' marā sin sasat dī ha dunya, sabab mangandul kitaniyu kan Īsa Almasi.",
        5: "Na, hangkan amura in di' marā sin sasat dī ha dunya, in manga sasuku' sin magparachaya sin hi Īsa amuna in Anak Tuhan.",
        6: "Na, biya' ha ini in tanda' piyakita' hi Īsa sin siya na tuud in limahil pa dunya (mamuas sin manga dusa sin mānusiya'). Muna-muna, nagpaligu' siya sin tubig. Hikaruwa, naasag in dugu' niya iban miyatay siya ha kalansang kaniya pa usuk. Na, in pagpaligu' iban sin pag'asag hi Īsa sin dugu' niya, amuna in tanda' sin siya na tuud in Almasi. Lāgi', in Rū sin Tuhan, amu in di' magpuputing, simaksi' da isab sin kasabunnalan pasal hi Īsa.",
        7: "In tū parakala' ini,",
        8: "in pagpaligu', in pag'asag sin dugu' hi Īsa iban sin bayta' sin Rū sin Tuhan, amuna in tumindug saksi' mamayta' sin bunnal tuud in hi Īsa amuna in Almasi. Na, magkugdan tuud in bayta' sin tū parakala' ini.",
        9: "Na, in kitaniyu magkahagad sin kasabunnalan saksian sin tau, na labi awla subay kitaniyu magkahagad sin kasabunnalan siyaksian sin Tuhan, sabab labi marayaw in saksi' niya. Siyaksian sin Tuhan sin in hi Īsa amuna in Anak niya.",
        10: "Na, hisiyu-siyu in magparachaya iban mangandul ha Anak Tuhan, na kaingatan niya ha lawm atay niya sin bunnal tuud in siyaksian sin Tuhan. Sagawa' hisiyu-siyu in di' magparachaya sin kasabunnalan biyayta' sin Tuhan sin in hi Īsa amuna in Anak niya, na biya' da siya imiyan in Tuhan putingan, sabab di' siya magkahagad sin kasabunnalan siyaksian sin Tuhan.",
        11: "Na, ini in kasabunnalan kabayaan sin Tuhan hipaingat kātu'niyu. Dayn ha pasal sin Anak niya, in kitaniyu dīhilan niya kabuhi' salama-lama.",
        12: "Hangkan hisiyu-siyu in himahambuuk tuud ha Anak Tuhan, na awn kabuhi' niya salama-lama, sagawa' hisiyu-siyu in wala' himahambuuk tuud ha Anak Tuhan, na wayruun kabuhi' niya salama-lama.",
        13: "Na, sulatan ta kamu, sasuku' sin kamu magparachaya ha Anak Tuhan, ha supaya niyu kaingatan sin awn na kabuhi' niyu salama-lama.",
        14: 'Wayruun kabugaan taniyu mangarap pa Tuhan, sabab kaingatan taniyu sin dungugun sin Tuhan in unu-unu pangayuun taniyu bang magkugdan iban sin kabayaan niya.',
        15: "Na, pagga natu' kaingatan na sin dungugun kitaniyu sin Tuhan ha sakaba' kitaniyu mangarap kaniya, na kaingatan natu' da isab sin dihilan niya kitaniyu sin unu-unu pangayuun natu' kaniya.",
        16: "Na, bang sawpama awn pagkahi niyu kakitaan niyu naghihinang sin makarusa, amu in dusa di' makarā pa kasiksaan salama-lama, pangayui niyu siya duwaa pa Tuhan, ha supaya siya maampun. Karihilan siya sin Tuhan kabuhi' salama-lama. Biya' ha yan in hinanga niyu ha manga tau, amu in nakarusa sin dusa, amu in di' makarā pa kasiksaan salama-lama. Tantu awn isab manga dusa amu in makarā pa kasiksaan salama-lama. Na, di' isab aku umiyan sin subay niyu pangayuan duwaa pa Tuhan in manga tau magdusa sin biya' ha yan, sabab way da pūs.",
        17: "Bunnal in katān hinang mangī' dusa, sagawa' awn dusa amu in di' makarā pa kasiksaan salama-lama.",
        18: "Na, kaingatan natu' sin sasuku' sin naitung na anak sin Tuhan bukun na tattap naghihinang sin makarusa, sabab iyaayaran sila dayn ha manga hinang mangī' kaagi sin Anak Tuhan, ampa sila di' magmula kaagi sin Iblis, amu in puunan sin katān mangī'.",
        19: "Kaingatan natu' sin in kitaniyu suku' na sin Tuhan, sagawa' in tau katān amu in nagpaparuli sadja sin kahālan sin dunya, in sila yan ha lawm lima sin Saytan Puntukan, amu in puunan sin katān mangī'.",
        20: "Kaingatan natu' sin in Almasi, amu in Anak Tuhan, bakas miyari pa dunya iban dīhilan niya kitaniyu panghāti marayaw, ha supaya natu' kaingatan bang hisiyu tuud in Tuhan bunnal. Naghahambuuk kitaniyu iban Tuhan sabab sin parachaya iban paghambuuk natu' iban hi Īsa Almasi, amu in Anak Tuhan. Na, amuna ini in Tuhan bunnal, amu in magdirihil sin kabuhi' salama-lama.",
        21: "Na, manga anak-apu' ku, halli' tuud kamu bat kamu di' marā sin sasat magtuhan ha unu-unu na dugaing dayn ha amu in bunnal tuud Tuhan! Wassalam.",
    },
}
